#!/usr/bin/env python3
"""
AIDD Adversarial Code Critic - PR Reviewer Script
Standard library only (zero external pip dependencies).
Supports Google Gemini API & OpenAI-compatible APIs.
"""

import os
import sys
import json
import subprocess
import urllib.request
import urllib.error

# Marker to identify comments generated by this tool
COMMENT_HEADER = "<!-- aidd-critic-review-bot -->"

def run_cmd(cmd):
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        print(f"Command failed: {cmd}\nError: {result.stderr}", file=sys.stderr)
        return ""
    return result.stdout.strip()

def get_pr_diff(base_ref):
    run_cmd(f"git fetch origin {base_ref} --depth=1")
    diff = run_cmd(f"git diff origin/{base_ref}...HEAD")
    return diff

def call_gemini(api_key, system_prompt, user_content):
    url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={api_key}"
    payload = {
        "contents": [
            {
                "role": "user",
                "parts": [
                    {"text": f"{system_prompt}\n\n---\n\n{user_content}"}
                ]
            }
        ],
        "generationConfig": {
            "temperature": 0.2,
            "maxOutputTokens": 4096
        }
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=120) as resp:
        data = json.loads(resp.read().decode("utf-8"))
        candidates = data.get("candidates", [])
        if candidates and "content" in candidates[0]:
            parts = candidates[0]["content"].get("parts", [])
            if parts and "text" in parts[0]:
                return parts[0]["text"]
    raise RuntimeError("Failed to parse response from Gemini API")

def call_openai_compatible(api_key, api_base, model, system_prompt, user_content):
    url = f"{api_base.rstrip('/')}/chat/completions"
    payload = {
        "model": model or "gpt-4o",
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_content}
        ]
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}"
        }
    )
    with urllib.request.urlopen(req, timeout=120) as resp:
        data = json.loads(resp.read().decode("utf-8"))
        choices = data.get("choices", [])
        if choices and "message" in choices[0]:
            return choices[0]["message"].get("content", "")
    raise RuntimeError("Failed to parse response from OpenAI API")

def post_or_update_comment(github_token, repo, pr_number, body):
    headers = {
        "Authorization": f"Bearer {github_token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json"
    }
    
    # 1. Check existing comments to find previous critic reviews
    list_url = f"https://api.github.com/repos/{repo}/issues/{pr_number}/comments"
    req = urllib.request.Request(list_url, headers=headers)
    existing_comment_id = None
    try:
        with urllib.request.urlopen(req) as resp:
            comments = json.loads(resp.read().decode("utf-8"))
            for c in comments:
                if COMMENT_HEADER in c.get("body", ""):
                    existing_comment_id = c.get("id")
                    break
    except Exception as e:
        print(f"Warning: Could not list comments: {e}", file=sys.stderr)

    full_body = f"{COMMENT_HEADER}\n\n{body}"
    payload = json.dumps({"body": full_body}).encode("utf-8")

    # 2. Update existing comment or create a new one
    if existing_comment_id:
        update_url = f"https://api.github.com/repos/{repo}/issues/comments/{existing_comment_id}"
        req = urllib.request.Request(update_url, data=payload, headers=headers, method="PATCH")
        with urllib.request.urlopen(req) as resp:
            print(f"Updated existing PR comment ID: {existing_comment_id}")
    else:
        post_url = f"https://api.github.com/repos/{repo}/issues/{pr_number}/comments"
        req = urllib.request.Request(post_url, data=payload, headers=headers, method="POST")
        with urllib.request.urlopen(req) as resp:
            print(f"Created new PR comment on PR #{pr_number}")

def main():
    github_token = os.environ.get("GITHUB_TOKEN")
    repo = os.environ.get("GITHUB_REPOSITORY")
    base_ref = os.environ.get("GITHUB_BASE_REF", "main")
    pr_number = os.environ.get("PR_NUMBER")

    if not github_token or not repo or not pr_number:
        print("Missing required environment variables (GITHUB_TOKEN, GITHUB_REPOSITORY, PR_NUMBER).", file=sys.stderr)
        sys.exit(1)

    # Read system prompt & review checklist
    workspace_root = os.getcwd()
    critic_prompt_path = os.path.join(workspace_root, ".agent/agents/code-critic.md")
    checklist_path = os.path.join(workspace_root, ".agent/checklists/critic_code_review_checklist.md")

    system_prompt = "You are the Adversarial Code & Security Critic for an AI-Driven Development workflow."
    if os.path.exists(critic_prompt_path):
        with open(critic_prompt_path, "r", encoding="utf-8") as f:
            system_prompt = f.read()

    checklist_content = ""
    if os.path.exists(checklist_path):
        with open(checklist_path, "r", encoding="utf-8") as f:
            checklist_content = f.read()

    system_prompt += f"\n\n## Review Checklist\n{checklist_content}"

    # Get git diff
    diff = get_pr_diff(base_ref)
    if not diff:
        print("No diff found. Nothing to review.")
        post_or_update_comment(
            github_token, repo, pr_number,
            "### 🤖 AIDD Code Critic Review\n\n差分が検出されませんでした。レビュー対象のコード変更はありません。"
        )
        sys.exit(0)

    # Truncate if diff is excessively huge (> 60KB) to stay within LLM token limits safely
    if len(diff) > 60000:
        diff_snippet = diff[:60000] + "\n\n...[Diff truncated due to size limit]..."
    else:
        diff_snippet = diff

    user_content = (
        f"# PR #{pr_number} Code Review Request\n\n"
        f"以下のGit差分（Diff）を批判的かつ厳格にレビューしてください。\n"
        f"セキュリティ脆弱性（OWASP Top 10）、エッジケース、SOLID原則、パフォーマンスを徹底精査し、\n"
        f"判定を `APPROVE` または `REQUEST_CHANGES` で明確に下してください。\n\n"
        f"```diff\n{diff_snippet}\n```"
    )

    gemini_api_key = os.environ.get("GEMINI_API_KEY")
    openai_api_key = os.environ.get("OPENAI_API_KEY")
    openai_base = os.environ.get("OPENAI_API_BASE", "https://api.openai.com/v1")
    openai_model = os.environ.get("OPENAI_MODEL", "gpt-4o")

    review_result = ""
    if gemini_api_key:
        print("Calling Google Gemini API...")
        review_result = call_gemini(gemini_api_key, system_prompt, user_content)
    elif openai_api_key:
        print("Calling OpenAI API...")
        review_result = call_openai_compatible(openai_api_key, openai_base, openai_model, system_prompt, user_content)
    else:
        print("Error: Neither GEMINI_API_KEY nor OPENAI_API_KEY is configured.", file=sys.stderr)
        sys.exit(1)

    # Post comment to GitHub PR
    formatted_body = (
        f"### 🛡️ AIDD Code Critic Review Result\n\n"
        f"{review_result}\n\n"
        f"---\n"
        f"<sub>Reviewed by `.agent/agents/code-critic.md` via AIDD GitHub Actions CI</sub>"
    )
    post_or_update_comment(github_token, repo, pr_number, formatted_body)

    # Fail CI if changes are requested or critical issues detected
    fail_on_blocker = os.environ.get("FAIL_ON_BLOCKER", "true").lower() == "true"
    if fail_on_blocker and ("REQUEST_CHANGES" in review_result or "Must Fix" in review_result):
        print("Critic detected critical issues or requested changes. Marking CI as failed.")
        sys.exit(1)
    else:
        print("Critic review completed successfully without blocking issues.")
        sys.exit(0)

if __name__ == "__main__":
    main()
